<section class="panel profile-panel section-space"><h2>Email verification</h2><?php if(!ops_options()['email_verification_required']):?><p class="small muted">Optional in the current configuration.</p><?php endif;?><p class="small muted"><?=e(user()['email'])?> · <strong><?=user()['email_verified_at']?'Verified':(ops_mail_ready()?'Not verified':'Verification unavailable')?></strong></p>
<?php if(!user()['email_verified_at'] && ops_mail_ready()):?><form method="post"><?php csrf();?><input type="hidden" name="action" value="request_verification"><button class="button secondary">Send verification email</button></form><p class="small muted">Verification links expire after 24 hours. Check your spam folder too.</p><?php elseif(!user()['email_verified_at']):?><p class="small muted">Email delivery is not configured. <?php $email_recovery_count=(int)q('SELECT COUNT(*) FROM recovery_codes WHERE user_id=? AND used_at IS NULL',[user()['id']])->fetchColumn();if($email_recovery_count):?>You have <?=$email_recovery_count?> unused recovery codes for password recovery.<?php else:?>No unused recovery codes are saved for this account. Generate recovery codes below, or contact the System Admin if you cannot sign in.<?php endif;?> <?php if(geo_system()):?><a class="text-link" href="index.php?page=system">Review email readiness →</a><?php endif;?></p><?php endif;?></section>
